// Serves the production build in app/dist on the port given by the PORT env var.
// Unknown paths fall back to index.html so client-side routes such as /staking work.
import { createReadStream, existsSync, statSync } from "node:fs"
import { createServer } from "node:http"
import { extname, join, normalize, resolve } from "node:path"
import { dirname } from "node:path"
import { fileURLToPath } from "node:url"

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "app", "dist")
const port = Number(process.env.PORT)
if (!process.env.PORT || !Number.isInteger(port) || port <= 0) {
	console.error("PORT must be set to a port number, e.g. PORT=8080 npm run serve")
	process.exit(1)
}
if (!existsSync(join(root, "index.html"))) {
	console.error("No production build found. Run `npm run build` first.")
	process.exit(1)
}

const TYPES = {
	".html": "text/html; charset=utf-8",
	".js": "text/javascript; charset=utf-8",
	".css": "text/css; charset=utf-8",
	".json": "application/json",
	".svg": "image/svg+xml",
	".png": "image/png",
	".ico": "image/x-icon",
	".wasm": "application/wasm",
	".woff2": "font/woff2",
}

const server = createServer((req, res) => {
	const pathname = decodeURIComponent(new URL(req.url ?? "/", "http://x").pathname)
	let file = normalize(join(root, pathname))
	if (!file.startsWith(root)) {
		res.writeHead(403).end("Forbidden")
		return
	}
	if (!existsSync(file) || statSync(file).isDirectory()) {
		file = join(root, "index.html")
	}
	res.writeHead(200, {
		"Content-Type": TYPES[extname(file)] ?? "application/octet-stream",
	})
	createReadStream(file).pipe(res)
})

server.listen(port, () => {
	console.log(`Serving ${root} on http://localhost:${port}`)
})
EOF
timeout 600 npm run build 2>&1 | tail -6

